"""Fixed external KAT values, plus boundary/tamper checks of vendored AEAD."""

import pytest

from src.web.ascon.ascon import ascon_decrypt, ascon_encrypt

# ascon/ascon-c, crypto_aead/asconaead128/LWC_AEAD_KAT_128_128.txt,
# Counts 1, 2, 34, 35, retrieved 2026-11-08. These ciphertexts are independent
# expectations copied from the reference project, not generated by pyascon.
# https://github.com/ascon/ascon-c/blob/main/crypto_aead/asconaead128/LWC_AEAD_KAT_128_128.txt
@pytest.mark.parametrize('pt,ad,expected', [
    ('', '', '4F9C278211BEC9316BF68F46EE8B2EC6'),
    ('', '30', 'CCCB674FE18A09A285D6AB11B35675C0'),
    ('20', '', 'E8DD576ABA1CD3E6FC704DE02AEDB79588'),
    ('20', '30', '962B8016836C75A7D86866588CA245D886'),
])
def test_reference_vectors(pt, ad, expected):
    key, nonce = bytes(range(16)), bytes(range(16, 32))
    pt, ad, expected = bytes.fromhex(pt), bytes.fromhex(ad), bytes.fromhex(expected)
    assert ascon_encrypt(key, nonce, ad, pt) == expected
    assert ascon_decrypt(key, nonce, ad, expected) == pt


@pytest.mark.parametrize('plen', [0, 1, 7, 8, 15, 16, 17, 31, 32])
@pytest.mark.parametrize('alen', [0, 1, 7, 8, 15, 16, 17, 31, 32])
def test_boundaries_and_authentication(plen, alen):
    key, nonce = bytes(range(16)), bytes(range(16, 32))
    pt, ad = bytes(range(plen)), bytes(range(alen))
    ct = ascon_encrypt(key, nonce, ad, pt)
    assert len(ct) == plen + 16
    assert ascon_decrypt(key, nonce, ad, ct) == pt
    assert ascon_decrypt(key, nonce, ad, ct[:-1] + bytes([ct[-1] ^ 1])) is None
    assert ascon_decrypt(key, nonce, ad + b'x', ct) is None
    assert ascon_decrypt(bytes([key[0] ^ 1]) + key[1:], nonce, ad, ct) is None
    assert ascon_decrypt(key, bytes([nonce[0] ^ 1]) + nonce[1:], ad, ct) is None
